/* src/mdbp_runtime.c -- the token vector, the derivation buffer, yylex, and
 * the token tables built once from bison's own yytname[]/yytranslate[].
 *
 * Nothing here knows anything about bison's internals (that is
 * src/parser_glue.c's job) and nothing here knows anything about the public
 * API (src/mdbp_api.c's job).
 */
#include <stdlib.h>
#include <string.h>

#include "mdbp_internal.h"

#include "mdbp_once.h"

/* The token tables, built once per process from bison's own yytname[] and
 * yytranslate[] (src/parser_glue.c), and read-only afterwards.  Nothing here
 * is generated by a script, so a hand edit of generated/yy_stub.yy cannot
 * leave a stale table behind. */
typedef struct mdbp_terminal {
    const char *name;
    int token_number;
} mdbp_terminal;

static mdbp_once_t mdbp_tables_once = MDBP_ONCE_INIT;
static const char **mdbp_kind_names;     /* [YYNTOKENS], NULL for undefined */
static mdbp_terminal *mdbp_terminals;    /* sorted by name, for bsearch */
static size_t mdbp_nterminals;

static int mdbp_terminal_sort_cmp(const void *a, const void *b)
{
    return strcmp(((const mdbp_terminal *) a)->name,
                  ((const mdbp_terminal *) b)->name);
}

static void mdbp_build_tables(void)
{
    int ntokens = mdbp_yy_ntokens();
    int maxutok = mdbp_yy_maxutok();
    int *kind_token;
    const char **names;
    mdbp_terminal *terminals;
    size_t n = 0;
    int kind;
    int t;

    names = (const char **) calloc((size_t) ntokens, sizeof *names);
    kind_token = (int *) malloc((size_t) ntokens * sizeof *kind_token);
    terminals = (mdbp_terminal *) calloc((size_t) ntokens, sizeof *terminals);
    if (names == NULL || kind_token == NULL || terminals == NULL) {
        free(names);
        free(kind_token);
        free(terminals);
        return; /* lookups answer -1 / NULL; the parse reports internal */
    }
    for (kind = 0; kind < ntokens; kind++) {
        kind_token[kind] = -1;
    }
    /* yytranslate maps token number -> kind; invert it.  Every number the
     * grammar does not declare maps to the undefined kind (2), skipped. */
    kind_token[0] = 0;
    for (t = 1; t <= maxutok; t++) {
        kind = mdbp_yy_translate(t);
        if (kind > 2 && kind < ntokens && kind_token[kind] < 0) {
            kind_token[kind] = t;
        }
    }
    kind_token[1] = 256; /* bison's error token */

    for (kind = 0; kind < ntokens; kind++) {
        const char *name;

        if (kind == 0) {
            name = "$end";              /* bison spells it "end of file" */
        } else if (kind == 2) {
            name = NULL;                /* bison's "invalid token" */
        } else {
            name = mdbp_yy_tname(kind);
        }
        names[kind] = name;
        if (name != NULL && kind_token[kind] >= 0) {
            terminals[n].name = name;
            terminals[n].token_number = kind_token[kind];
            n++;
        }
    }
    qsort(terminals, n, sizeof *terminals, mdbp_terminal_sort_cmp);
    free(kind_token);

    mdbp_kind_names = names;
    mdbp_terminals = terminals;
    mdbp_nterminals = n;
}

static void mdbp_tables(void)
{
    mdbp_once(&mdbp_tables_once, mdbp_build_tables);
}

static int mdbp_terminal_cmp(const void *key, const void *element)
{
    return strcmp((const char *) key, ((const mdbp_terminal *) element)->name);
}

int mdbp_token_number(const char *name)
{
    const mdbp_terminal *hit;

    if (name == NULL) {
        return -1;
    }
    mdbp_tables();
    if (mdbp_terminals == NULL) {
        return -1;
    }
    hit = (const mdbp_terminal *) bsearch(name, mdbp_terminals,
                                          mdbp_nterminals,
                                          sizeof mdbp_terminals[0],
                                          mdbp_terminal_cmp);
    return hit == NULL ? -1 : hit->token_number;
}

const char *mdbp_symbol_name(int kind)
{
    mdbp_tables();
    if (mdbp_kind_names == NULL || kind < 0 || kind >= mdbp_yy_ntokens()) {
        return NULL;
    }
    return mdbp_kind_names[kind];
}

/* --- the context --------------------------------------------------------- */

void mdbp_ctx_init(mdbp_ctx *ctx, const mdbp_token *tokens, size_t ntokens,
                   int want_derivation)
{
    memset(ctx, 0, sizeof *ctx);
    /* The lifted grammar actions reach the field through five
     * spellings, two of them via `thd->lex`, which generated/yy_stub.yy's
     * prologue resolves to `ctx->ctx`.  Set it HERE, once, where the struct
     * is made: an mdbp_ctx with a NULL self-pointer would segfault in the
     * first action that runs, not at some later boundary. */
    ctx->ctx = ctx;
    ctx->current_select = &ctx->own_select;
    ctx->tokens = tokens;
    ctx->ntokens = ntokens;
    ctx->lookahead_index = 0;
    ctx->want_derivation = want_derivation;
    ctx->error_state = -1;
}

void mdbp_ctx_reset(mdbp_ctx *ctx, const mdbp_token *tokens, size_t ntokens)
{
    ctx->tokens = tokens;
    ctx->ntokens = ntokens;
    /* Back to our OWN storage, and back to NO_MATTER.  The previous record
     * may have been a live parse, in which case current_select pointed into a
     * lexer this record's caller has already freed; mdbp_parse_sql() re-points
     * it at the new one after mdbp_lex_new(). */
    ctx->current_select = &ctx->own_select;
    ctx->own_select.parsing_place = NO_MATTER;
    ctx->own_select.save_parsing_place = NO_MATTER;
    /* Cleared, not kept: one parser serves both mdbp_parse_sql() (the pull
     * path) and mdbp_parse_tokens() (a token vector), and a stale source
     * from the previous call would make this one ignore its own tokens.  The
     * caller re-arms it with mdbp_ctx_set_source() after every reset. */
    ctx->source = NULL;
    ctx->source_user = NULL;
    ctx->cursor = 0;
    ctx->lookahead_index = 0;
    /* the buffer and its capacity STAY; only the length goes back to zero */
    ctx->nderivation = 0;
    ctx->internal_error = 0;
    ctx->error_seen = 0;
    ctx->error_state = -1;
    ctx->error_message = NULL;
    /* parser_glue.c mallocs this per rejected parse: hand it back now or the
     * parser leaks once per rejection for as long as it lives. */
    free((void *) ctx->expected);
    ctx->expected = NULL;
    ctx->nexpected = 0;
}

void mdbp_ctx_free(mdbp_ctx *ctx)
{
    free(ctx->derivation);
    ctx->derivation = NULL;
    free(ctx->derivation_depth);
    ctx->derivation_depth = NULL;
    ctx->derivation_cap = 0;
    ctx->nderivation = 0;
    free((void *) ctx->expected);
    ctx->expected = NULL;
    ctx->nexpected = 0;
}

/* --- the derivation ------------------------------------------------------ */

void mdbp_reduce(mdbp_ctx *ctx, int rule, int depth)
{
    if (!ctx->want_derivation || ctx->internal_error) {
        return;
    }
    if (rule < 1 || rule >= mdbp_yy_nrules()) {
        /* Unreachable: the rule number is bison's own yyn - 1.  Silence is
         * not an option, so it becomes an internal error rather than a
         * wrong derivation. */
        ctx->internal_error = 1;
        return;
    }
    if (ctx->nderivation == ctx->derivation_cap) {
        size_t want = ctx->derivation_cap ? ctx->derivation_cap * 2 : 256;
        int *grown = (int *) realloc(ctx->derivation, want * sizeof *grown);
        int *grown_depth;
        if (grown == NULL) {
            ctx->internal_error = 1;
            return;
        }
        ctx->derivation = grown;
        grown_depth = (int *) realloc(ctx->derivation_depth, want * sizeof *grown_depth);
        if (grown_depth == NULL) {
            ctx->internal_error = 1;
            return;
        }
        ctx->derivation_depth = grown_depth;
        ctx->derivation_cap = want;
    }
    ctx->derivation_depth[ctx->nderivation] = depth;
    ctx->derivation[ctx->nderivation++] = rule;
}

/* --- the lexer ----------------------------------------------------------- */

void mdbp_ctx_set_source(mdbp_ctx *ctx, mdbp_source_fn source, void *user)
{
    ctx->source = source;
    ctx->source_user = user;
}

int yylex(int *lvalp, mdbp_ctx *ctx)
{
    /* The value stack is unused (every action is a stub), but bison copies
     * *lvalp onto it, so it must be initialised. */
    *lvalp = 0;

    if (ctx->source != NULL) {
        /* THE PULL PATH (mdbp_parse_sql()): the parser drives the lexer, so the
         * token does not exist until this call asks for it.  This is the only
         * way valid(T) can be answered from the live LR stack -- the lexer's
         * decision and the parser's state are the same instant -- and it is
         * what MariaDB itself does.
         *
         * A source that ends (0) or fails (-1) both return bison's $end: the
         * parse has to stop either way, and the CALLER, not this function,
         * decides what the failure means (an unknown terminal name is a
         * verdict of "unsupported", an allocation failure is "internal").
         * ctx->cursor keeps counting handed-over tokens exactly as below, so
         * mdbp_result.error_token_index indexes the lexed token vector
         * unchanged. */
        mdbp_token tok;
        int rc = ctx->source(ctx->source_user, &tok);

        if (rc <= 0) {
            ctx->lookahead_index = ctx->cursor;
            return 0;
        }
        ctx->lookahead_index = ctx->cursor++;
        return tok.token_number;
    }

    if (ctx->cursor >= ctx->ntokens) {
        /* The synthetic end of input.  It is NOT counted in cursor, and
         * lookahead_index becomes ntokens, which is what
         * mdbp_result.error_token_index reports when the failure is at end
         * of input. */
        ctx->lookahead_index = ctx->ntokens;
        return 0;
    }
    ctx->lookahead_index = ctx->cursor;
    return ctx->tokens[ctx->cursor++].token_number;
}
